1.1 Probability and Events
Before we delve into statistical inference, we briefly review key ideas from probability theory.
When working with probability we need three basic ingredients1
We can write the definitions of complement, intersection and union formally with sets:
Visualisation:
// Toggle: highlight selection (use explicit values for robust comparisons)
viewof vennOp = Inputs.radio(
  ["None", "A", "B", "Aᶜ", "Union", "Intersection"],
  { value: "None", label: "Highlight:" }
)
venn = {
  const width = 480, height = 280;
  const pad = 18;

  const cxA = 190, cyA = 140, r = 90;   // circle A
  const cxB = 290, cyB = 140;           // circle B

  const svg = d3.create("svg")
    .attr("width", width)
    .attr("height", height)
    .attr("viewBox", [0, 0, width, height]);

  // Sample space Ω (bounding rectangle)
  const omega = svg.append("rect")
    .attr("x", pad).attr("y", pad)
    .attr("width", width - 2*pad).attr("height", height - 2*pad)
    .attr("rx", 10)
    .attr("fill", "none")
    .attr("stroke", "currentColor")
    .attr("stroke-opacity", 0.5);

  // Label Ω
  svg.append("text")
    .attr("x", pad + 8).attr("y", pad + 16)
    .text("Ω")
    .style("font-weight", 400)
    .style("font-size", "18px")
    .style("fill", "var(--fg-muted)");

  // Colors (CSS vars with fallbacks)
  const colA   = "var(--brand-teal, #14b8a6)";
  const colB   = "var(--brand-red, #ef4444)";
  const hilite = "var(--brand-orange, #F39C65)";
  const grid   = "var(--plot-grid, #94a3b8)";

  // --- Defs: clips & mask for A^c ---
  const defs = svg.append("defs");

  defs.append("clipPath").attr("id", "clipA")
    .append("circle").attr("cx", cxA).attr("cy", cyA).attr("r", r);

  defs.append("clipPath").attr("id", "clipB")
    .append("circle").attr("cx", cxB).attr("cy", cyB).attr("r", r);

  // Mask for A^c: white keeps, black removes (subtract circle A from Ω rect)
  const m = defs.append("mask").attr("id", "maskAc");
  m.append("rect")
    .attr("x", pad).attr("y", pad)
    .attr("width", width - 2*pad).attr("height", height - 2*pad)
    .attr("rx", 10)
    .attr("fill", "white");
  m.append("circle")
    .attr("cx", cxA).attr("cy", cyA).attr("r", r)
    .attr("fill", "black");

  // Base sets (always lightly transparent)
  svg.append("circle")
    .attr("cx", cxA).attr("cy", cyA).attr("r", r)
    .attr("fill", colA).attr("fill-opacity", 0.4);

  svg.append("circle")
    .attr("cx", cxB).attr("cy", cyB).attr("r", r)
    .attr("fill", colB).attr("fill-opacity", 0.4);

  // Highlight layer
  if (vennOp === "A") {
    svg.append("circle")
      .attr("cx", cxA).attr("cy", cyA).attr("r", r)
      .attr("fill", hilite).attr("fill-opacity", 0.99);

  } else if (vennOp === "B") {
    svg.append("circle")
      .attr("cx", cxB).attr("cy", cyB).attr("r", r)
      .attr("fill", hilite).attr("fill-opacity", 0.99);

  } else if (vennOp === "Aᶜ") {
    // Draw Ω in orange, but masked to remove A
    svg.append("rect")
      .attr("x", pad).attr("y", pad)
      .attr("width", width - 2*pad).attr("height", height - 2*pad)
      .attr("rx", 10)
      .attr("fill", hilite).attr("fill-opacity", 0.99)
      .attr("mask", "url(#maskAc)");

  } else if (vennOp === "Union") {
    // A ∪ B: overlay both circles solid orange
    svg.append("circle")
      .attr("cx", cxA).attr("cy", cyA).attr("r", r)
      .attr("fill", hilite).attr("fill-opacity", 0.99);
    svg.append("circle")
      .attr("cx", cxB).attr("cy", cyB).attr("r", r)
      .attr("fill", hilite).attr("fill-opacity", 0.99);

  } else if (vennOp === "Intersection") {
    // A ∩ B: clip B by A (equivalently clip A by B)
    svg.append("g").attr("clip-path", "url(#clipA)")
      .append("circle")
      .attr("cx", cxB).attr("cy", cyB).attr("r", r)
      .attr("fill", hilite).attr("fill-opacity", 0.99);
  }

  // Labels A and B
  svg.append("text")
    .attr("x", cxA - 26).attr("y", cyA - 8)
    .text("A")
    .style("font-size", "14px")
    .style("font-weight", 600)
    .style("fill", "var(--fg-muted)");

  svg.append("text")
    .attr("x", cxB + 22).attr("y", cyB - 8)
    .text("B")
    .style("font-size", "14px")
    .style("font-weight", 600)
    .style("fill", "var(--fg-muted)");

  // Subtle baseline
  svg.append("line")
    .attr("x1", pad).attr("x2", width - pad)
    .attr("y1", height - pad - 0.5).attr("y2", height - pad - 0.5)
    .attr("stroke", grid).attr("stroke-opacity", 0.2);

  return svg.node();
}








Figure 1.1: Venn diagram of two events \(A\) and \(B\) inside the sample space \(\Omega\).
Visualisation:
{
  const width = 720, height = 360;
  const pad = 20;

  // colour cycle from theme accents
  const brand = [
    "var(--brand-teal, #55C3CB)",
    "var(--brand-orange, #F39C65)",
    "var(--brand-purple, #A180DA)",
    "var(--brand-mint, #DDFFEB)",
    "var(--brand-red, #e65660)"
  ];
  const col = i =&gt; brand[i % brand.length];

  // seeded RNG so "Reseed" changes layout deterministically per click
  const rng = d3.randomLcg(reseed || 1);

  // generate n sites inside Ω (inset by padding)
  const sites = d3.range(n).map(i =&gt; ({
    name: `B${i+1}`,
    x: pad + rng() * (width - 2*pad),
    y: pad + rng() * (height - 2*pad)
  }));

  const delaunay = d3.Delaunay.from(sites, d =&gt; d.x, d =&gt; d.y);
  const vor = delaunay.voronoi([pad, pad, width - pad, height - pad]);

  const svg = d3.create("svg")
    .attr("viewBox", [0, 0, width, height])
    .attr("width", width)
    .attr("height", height)
    .style("background", "var(--brand-bg)")
    .style("font-family", bodyFont)
    .style("font-size", "14px");

  // --- defs: rounded-rect clip for Ω ---
  const defs = svg.append("defs");
  defs.append("clipPath")
    .attr("id", "clipOmega")
    .append("rect")
      .attr("x", pad).attr("y", pad)
      .attr("width", width - 2*pad).attr("height", height - 2*pad)
      .attr("rx", 10);

  // cells (clipped to rounded Ω so no sharp outer box)
  const g = svg.append("g").attr("clip-path", "url(#clipOmega)");
  const polys = [];  // store polygons for centroid labelling

  for (let i = 0; i &lt; sites.length; i++) {
    const poly = vor.cellPolygon(i);
    if (!poly) continue;
    polys.push({ i, poly, name: sites[i].name });
    g.append("path")
      .attr("d", d3.line()(poly))
      .attr("fill", col(i))
      .attr("fill-opacity", 0.2)
      .attr("stroke", "currentColor")
      .attr("stroke-opacity", 0.28);
  }

  // label font size adapts to n (clamped between 10px and 14px)
  const fz = Math.max(10, Math.min(14, 16 - 0.5 * (n - 3)));

  // labels at polygon centroids (true centre for convex Voronoi cells)
  svg.append("g")
    .selectAll("text")
    .data(polys.map(d =&gt; {
      const [cx, cy] = d3.polygonCentroid(d.poly);
      return { x: cx, y: cy, name: d.name };
    }))
    .join("text")
      .attr("x", d =&gt; d.x)
      .attr("y", d =&gt; d.y)
      .text(d =&gt; d.name)
      .attr("font-weight", 700)
      .attr("fill", "currentColor")
      .attr("font-size", `${fz}px`)
      .attr("text-anchor", "middle")
      .attr("dominant-baseline", "middle");

  // Ω frame (single rounded rectangle, drawn last)
  svg.append("rect")
    .attr("x", pad).attr("y", pad)
    .attr("width", width - 2*pad).attr("height", height - 2*pad)
    .attr("rx", 10)
    .attr("fill", "none")
    .attr("stroke", "currentColor")
    .attr("stroke-opacity", 0.55);

  // Ω label
  svg.append("text")
    .attr("x", pad + 8).attr("y", pad + 16)
    .text("Ω")
    .style("font-weight", 400)
    .style("font-size", "18px")
    .attr("fill", "currentColor");

  return svg.node();
}








Figure 1.2: A decomposition of the sample space \(\Omega\) into a partition \(B_1,\ldots,B_k\). Subsets \(B_i\) are mutually exclusive and exhaustive; every point in \(\Omega\) lies in exactly one \(B_i\).
html`&lt;style&gt;
/* ---------- Scope all styles to this controls box ---------- */
details.controls-root { 
  --ctrl-font: 12px;
  font-size: var(--ctrl-font);
}

/* Dropdown header */
details.controls-root &gt; summary {
  list-style: none; cursor: pointer; user-select: none;
  background: var(--surface, #f1f5f9);
  border: 1px solid var(--border, #e5e7eb);
  border-radius: 10px;
  padding: 8px 10px;
  font-weight: 600; font-size: calc(var(--ctrl-font) + 1px);
  color: var(--fg-strong, #334155);
  display: flex; align-items: center; gap: 8px;
}
details.controls-root &gt; summary::-webkit-details-marker { display: none; }
details.controls-root[open] &gt; summary { border-bottom-left-radius: 0; border-bottom-right-radius: 0; }

/* Two-column grid (side-by-side) */
details.controls-root .controls-grid {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) minmax(260px, 1fr);
  gap: 12px;
  border: 1px solid var(--border, #e5e7eb); border-top: none;
  border-bottom-left-radius: 10px; border-bottom-right-radius: 10px;
  padding: 10px;
  background: var(--surface-weak, #fafafa);
  overflow-x: auto;
}
details.controls-root .controls-col { min-width: 260px; }
details.controls-root .controls-col h4 {
  margin: 0 0 6px 0;
  font-size: var(--ctrl-font); font-weight: 700;
  color: var(--fg-muted, #475569);
}

/* ---- Align label & slider (form-level grid) ---- */
details.controls-root .controls-col form {
  display: grid !important;
  grid-template-columns: minmax(150px, auto) 1fr; /* label | inputs */
  align-items: center;         /* vertical centring */
  column-gap: 10px;
  font-size: var(--ctrl-font) !important;
  line-height: 1.25;
  margin: 6px 0;
}

/* Label: kill default &lt;p&gt; margin; align KaTeX + text */
details.controls-root .controls-col form &gt; label {
  margin: 0 !important;
  display: flex; align-items: center; gap: 8px;
  font-size: var(--ctrl-font) !important;
  color: var(--fg-muted, #475569);
  font-weight: 600;
}
details.controls-root .controls-col form &gt; label p { margin: 0 !important; }

/* Inputs wrapper (auto-generated, e.g. .oi-*-input): align number + slider */
details.controls-root .controls-col form &gt; [class$="-input"],
details.controls-root .controls-col form &gt; [class*="-input"] {
  display: flex; align-items: center; gap: 8px;
  min-height: 22px;
}

/* Number input normalisation */
details.controls-root .controls-col input[type="number"] {
  height: 24px; padding: 2px 6px;
  font-size: var(--ctrl-font);
  border: 1px solid var(--border, #e5e7eb); border-radius: 6px;
  background: var(--surface, #f1f5f9); color: var(--fg-strong, #334155);
}

/* Slider styling */
details.controls-root .controls-col input[type="range"] {
  -webkit-appearance: none; appearance: none;
  width: 100%; height: 18px; background: transparent;
  vertical-align: middle;
  accent-color: var(--brand-teal, #55C3CB);
}
details.controls-root .controls-col input[type="range"]::-webkit-slider-runnable-track {
  height: 4px; border-radius: 999px;
  background: color-mix(in srgb, var(--brand-teal, #55C3CB) 35%, transparent);
}
details.controls-root .controls-col input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none; appearance: none;
  width: 12px; height: 12px; border-radius: 50%;
  background: var(--brand-teal, #55C3CB); border: 0; margin-top: -4px; /* centre thumb over 4px track */
}
details.controls-root .controls-col input[type="range"]::-moz-range-track {
  height: 4px; border-radius: 999px;
  background: color-mix(in srgb, var(--brand-teal, #55C3CB) 35%, transparent);
}
details.controls-root .controls-col input[type="range"]::-moz-range-thumb {
  width: 12px; height: 12px; border-radius: 50%;
  background: var(--brand-teal, #55C3CB); border: 0;
}

/* Button */
details.controls-root .btn-resim button {
  background: var(--brand-teal, #55C3CB); color: #fff;
  border: none; border-radius: 6px; padding: 6px 12px;
  font-weight: 600; font-size: var(--ctrl-font); cursor: pointer;
  transition: filter 120ms ease, background-color 120ms ease;
}
details.controls-root .btn-resim button:hover {
  background: color-mix(in srgb, var(--brand-teal, #55C3CB) 88%, black);
}

/* Chevron */
details.controls-root &gt; summary::before {
  content: ""; display: inline-block; margin-right: 8px; width: 0; height: 0;
  border-style: solid; border-width: 3px 0 3px 6px;
  border-color: transparent transparent transparent var(--fg-strong);
  transform: rotate(0deg); transform-origin: 3px 50%; transition: transform 50ms ease;
}
details.controls-root[open] &gt; summary::before { transform: rotate(90deg); }

/* Optional: match plot width and center the controls block */
.controls-wrap { max-width: 720px; margin: 8px auto 0; }
&lt;/style&gt;`







viewof controls = {
  const resBtn = Inputs.button("Reseed points");
  resBtn.classList.add("btn-resim");

  const leftForm = Inputs.form(
    { n: Inputs.range([3, 50], { value: 10, step: 1, label: md`${tex`k`}: number of sets` }) },
    { submit: false }
  );
  const rightForm = Inputs.form({ reseed: resBtn }, { submit: false });

  const root = html`&lt;div class="controls-wrap"&gt;
    &lt;details class="controls-root" open&gt;
      &lt;summary&gt;Partition controls&lt;/summary&gt;
      &lt;div class="controls-grid"&gt;
        &lt;div class="controls-col"&gt;&lt;h4&gt;Number of regions&lt;/h4&gt;&lt;/div&gt;
        &lt;div class="controls-col"&gt;&lt;h4&gt;Randomisation&lt;/h4&gt;&lt;/div&gt;
      &lt;/div&gt;
    &lt;/details&gt;
  &lt;/div&gt;`;

  const grid = root.querySelector(".controls-grid");
  const leftCol = grid.children[0];
  const rightCol = grid.children[1];
  leftCol.append(leftForm);
  rightCol.append(rightForm);

  const getValue = () =&gt; ({ ...leftForm.value, ...rightForm.value });
  const update = () =&gt; {
    root.value = getValue();
    root.dispatchEvent(new CustomEvent("input", { bubbles: true }));
  };
  grid.addEventListener("input", update);
  queueMicrotask(update);
  return root;
}

// reactive bindings for the plot
n = controls.n
reseed = controls.reseed
Visualisation:
{
  const width = 720, height = 360;
  const pad = 20;

  // colours
  const brand = [
    "var(--brand-teal, #55C3CB)",
    "var(--brand-purple, #A180DA)",
    "var(--brand-mint, #DDFFEB)",
    "var(--brand-red, #e65660)"
  ];
  const col = i =&gt; brand[i % brand.length];
  const orange = "var(--brand-orange, #F39C65)";

  // deterministic RNG
  const rng = d3.randomLcg(2);

  // Voronoi sites
  const sites = d3.range(n2).map(i =&gt; ({
    name: `B${i+1}`,
    x: pad + rng() * (width - 2*pad),
    y: pad + rng() * (height - 2*pad)
  }));

  const delaunay = d3.Delaunay.from(sites, d =&gt; d.x, d =&gt; d.y);
  const vor = delaunay.voronoi([pad, pad, width - pad, height - pad]);

  const svg = d3.create("svg")
    .attr("viewBox", [0, 0, width, height])
    .attr("width", width)
    .attr("height", height)
    .style("background", "var(--brand-bg)")
    .style("font-family", bodyFont)
    .style("font-size", "14px");

  // --- defs: rounded-rect clip for Ω + per-cell clipPaths + ellipse for A ---
  const defs = svg.append("defs");

  defs.append("clipPath")
    .attr("id", "clipOmega-lotp2")
    .append("rect")
      .attr("x", pad).attr("y", pad)
      .attr("width", width - 2*pad).attr("height", height - 2*pad)
      .attr("rx", 10);

  // Per-cell clipPaths (so we can draw A∩B_i by clipping the ellipse to each cell)
  for (let i = 0; i &lt; sites.length; i++) {
    const poly = vor.cellPolygon(i);
    if (!poly) continue;
    defs.append("clipPath")
      .attr("id", `clipCell-lotp2-${i}`)
      .append("path")
      .attr("d", d3.line()(poly));
  }

  // A: ellipse geometry
  const Ax = width * 0.50, Ay = height * 0.52;  // centre
  const Arx = width * 0.42, Ary = height * 0.4;

  // Draw A outline (thin) so learners see the target set even before fills
  svg.append("ellipse")
    .attr("cx", Ax).attr("cy", Ay)
    .attr("rx", Arx).attr("ry", Ary)
    .attr("fill", "none")
    .attr("stroke", orange)
    .attr("stroke-width", 2)
    .attr("clip-path", "url(#clipOmega-lotp2)");

  // --- Voronoi cells: visible strokes on TOP of orange pieces ---
  const strokes = svg.append("g").attr("clip-path", "url(#clipOmega-lotp2)");
  const polys = [];
  for (let i = 0; i &lt; sites.length; i++) {
    const poly = vor.cellPolygon(i);
    if (!poly) continue;
    polys.push({ i, poly, name: sites[i].name });
    strokes.append("path")
      .attr("d", d3.line()(poly))
      .attr("stroke", "currentColor")
      .attr("fill", col(i))
      .attr("fill-opacity", 0.2)
      .attr("stroke-opacity", 0.55);
  }

  // Labels at polygon centroids; adaptive font size
  const fz2 = Math.max(10, Math.min(14, 16 - 0.3 * (n2 - 3)));
  svg.append("g")
    .selectAll("text")
    .data(polys.map(d =&gt; {
      const [cx, cy] = d3.polygonCentroid(d.poly);
      return { x: cx, y: cy, name: d.name };
    }))
    .join("text")
      .attr("x", d =&gt; d.x)
      .attr("y", d =&gt; d.y)
      .text(d =&gt; d.name)
      .attr("font-weight", 700)
      .attr("fill", "var(--fg-muted)")
      .attr("font-size", `${fz2}px`)
      .attr("text-anchor", "middle")
      .attr("dominant-baseline", "middle");

  // --- A∩B_i pieces (orange), revealed up to 'frame2' ---
  const overlaps = svg.append("g").attr("clip-path", "url(#clipOmega-lotp2)");
  for (let i = 0; i &lt; sites.length; i++) {
    overlaps.append("ellipse")
      .attr("cx", Ax).attr("cy", Ay)
      .attr("rx", Arx).attr("ry", Ary)
      .attr("fill", orange)
      .attr("fill-opacity", i &lt; frame2 ? 1. : 0)  // reveal progressively
      .attr("clip-path", `url(#clipCell-lotp2-${i})`);
  }


  // Ω frame
  svg.append("rect")
    .attr("x", pad).attr("y", pad)
    .attr("width", width - 2*pad).attr("height", height - 2*pad)
    .attr("rx", 10)
    .attr("fill", "none")
    .attr("stroke", "currentColor")
    .attr("stroke-opacity", 0.55);

  // Ω label
  svg.append("text")
    .attr("x", pad + 8).attr("y", pad + 16)
    .text("Ω")
    .style("font-weight", 400)
    .style("font-size", "18px")
    .attr("fill", "currentColor");

  // A label
  svg.append("text")
    .attr("x", Ax).attr("y", Ay)
    .text("A")
    .attr("fill", "currentColor")
    .attr("font-size", 18)
    .attr("font-weight", 700)
    .attr("text-anchor", "middle");

  return svg.node();
}








Figure 1.3: Law of Total Probability visualised. An event \(A\) (orange) overlaps a partition \(B_1,\ldots,B_{k}\) of \(\Omega\). The shaded pieces \(A\cap B_i\) decompose \(\operatorname{Pr}(A)\) as \(\operatorname{Pr}(A)= \sum_i \operatorname{Pr}(A \cap B_i)\).
// Animation driver: each button click restarts the reveal
frame2 = {
  if (!click2) return 0;
  const delay = 600;
  let i = 0;
  while (i &lt;= n2) {
    yield i;
    await Promises.delay(delay);
    i++;
  }
  return i;
}
